import{_ as i,l as o,o as e,c as l,v as n,p as s,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"劳动收入风险与保险","description":"","frontmatter":{"title":"劳动收入风险与保险","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/income-risk-insurance.md","filePath":"econ/income-risk-insurance.md","lastUpdated":1789023840000}'),E={name:"econ/income-risk-insurance.md"};function A(u,a,m,B,h,_){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="劳动收入风险与保险" tabindex="-1">劳动收入风险与保险 <a class="header-anchor" href="#劳动收入风险与保险" aria-label="Permalink to &quot;劳动收入风险与保险&quot;">​</a></h1><div class="epigraph"><p>消费对收入冲击的传递系数，测量市场与家庭提供了多少保险；完全市场是零传递，自保是缓冲存量。</p><footer>—— Blundell, Pistaferri and Preston, Consumption Inequality and Partial Insurance, AER 2008；Kaplan and Violante 对不完全保险模型的对照</footer></div><p><a href="/econ/intergenerational-mobility">上一课</a>把 \\(z\\) 接到跨代投资。一代之内，\\(z\\) 仍在动。本课缺口是<strong>保险</strong>：哪些冲击被抹平，哪些进消费。不重写代际弹性，不把失业保险的道德风险提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完全市场：特异 \\(z\\) 不进个人 \\(c\\)。自保 Aiyagari：暂时冲击被缓冲，持久冲击进消费。Blundell–Pistaferri–Preston：用收入与消费的面板，估对持久/暂时冲击的传递。发现部分保险：既不是零也不是一。缺口是给 HANK 的收入过程一个可测的保险程度，而不是假设「不可保」等于「完全不保」。</p><p><span class="marginnote">Blundell, Pistaferri and Preston, <em>AER</em> 98(5), 2008, 1887–1921。Attanasio–Davis；Krueger–Perri 消费不平等。Heathcote, Storesletten and Violante 的定量保险。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把收入分成持久与暂时（或单位根加 MA）。消费增长对两类新息回归，控制家庭结构。模型侧：在 Aiyagari/HANK 里加进（或关掉）状态依存证券、破产、家庭内保险，使传递系数对上。宏观加总：特异风险的保险不影响总量 \\(C\\) 的一阶，但影响福利与 MPC 分布。</p>',8)),(e(),s(p,null,{default:t(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E6%94%B6%E5%85%A5%E6%96%B0%E6%81%AF%22%5D%20--%3E%20TR%5B%22%E6%9A%82%E6%97%B6%22%5D%0A%20%20INC%20--%3E%20PER%5B%22%E6%8C%81%E4%B9%85%22%5D%0A%20%20TR%20--%3E%20BUF%5B%22%E7%BC%93%E5%86%B2%20%2F%20%E4%BF%A1%E8%B4%B7%22%5D%0A%20%20PER%20--%3E%20C%5B%22%E6%9B%B4%E5%A4%9A%E8%BF%9B%E5%85%A5%20c%22%5D%0A%20%20MKT%5B%22%E5%B8%82%E5%9C%BA%E4%B8%8E%E5%AE%B6%E5%BA%AD%E4%BF%9D%E9%99%A9%22%5D%20--%3E%20PART%5B%22%E9%83%A8%E5%88%86%E4%BC%A0%E9%80%92%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>与股权溢价：总量消费平滑不能推断微观保险充分。本栏不把谜重做一遍，只禁止用 \\(C\\) 的平滑否定本课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是资产、家庭、破产法与税收的混合。持久冲击难以自保，因为要移动永久收入水平；暂时冲击像缓冲课已经写过的。累进税与转移提供政府保险，扭曲留给下一课 UI。房价与住房权益提取在某些国家是主要保险工具——与后课家庭债务接口。</p><p>识别：收入测量误差会把暂时冲击估大、保险估高。行政数据改善但不消灭模型设定误差。</p><p><span class="marginnote">Guvenen, Ozkan and Song 的行政收入过程显示偏斜与灾难式下降，校准若只用 AR(1) 会低估对保险的需求。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计最优失业保险公式（下一课道德风险）。不估计健康保险。不把人力资本不可逆投资与一年一度的 \\(z\\) 混成一个冲击。企业风险向工资的传递（Guiso 等）点名即可。</p><p>后课默认：部分保险由传递系数测量；持久冲击进 \\(c\\) 更多。下一课：专门把失业这种可观测冲击接到 UI 与搜寻激励。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>传递系数测量部分保险；完全市场与纯自保是两端。</li><li>暂时冲击靠缓冲，持久冲击难保。</li><li>总量 \\(C\\) 平滑不等于微观充分保险。</li><li>出处：Blundell, Pistaferri and Preston, <em>AER</em> 2008。</li></ul>',10))])}const T=i(E,[["render",A]]);export{f as __pageData,T as default};
